import { cn } from "@/registry/mbank/lib/utils"

/** Figma `segment` of the `Period` row (48px): list and item looks, shared with PeriodSegment. */
export const periodListClass = "flex w-full items-center gap-1 rounded-lg bg-surface-2 p-1 sm:w-fit"
export const periodItemClass =
  "inline-flex h-10 flex-1 items-center justify-center rounded-md px-2 text-sm whitespace-nowrap text-soft-foreground outline-none transition-colors hover:text-foreground focus-visible:ring-[3px] focus-visible:ring-ring/30 sm:flex-none sm:px-4 sm:text-base"
const activeClass = "bg-background text-foreground shadow-xs"

type PeriodSwitchProps<T extends string> = {
  value: T
  onValueChange: (value: T) => void
  options: { value: T; label: string }[]
  label?: string
  className?: string
}

/**
 * Figma `segment` (Сегодня / Неделя / Месяц / Квартал) on its own, e.g. in the page title row
 * next to a heading. Toggle buttons (aria-pressed): use PeriodSegment when it switches a panel.
 */
export function PeriodSwitch<T extends string>({ value, onValueChange, options, label = "Период", className }: PeriodSwitchProps<T>) {
  return (
    <div role="group" aria-label={label} data-slot="period-switch" className={cn(periodListClass, className)}>
      {options.map((option) => (
        <button
          key={option.value}
          type="button"
          aria-pressed={option.value === value}
          onClick={() => onValueChange(option.value)}
          className={cn(periodItemClass, option.value === value && activeClass)}
        >
          {option.label}
        </button>
      ))}
    </div>
  )
}

import type * as React from "react"

import { cn } from "@/registry/mbank/lib/utils"
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/registry/mbank/ui/tabs"
import { periodListClass } from "./PeriodSwitch"

export type PeriodOption<T extends string> = { value: T; label: string }

type PeriodSegmentProps<T extends string> = {
  /** Section title on the left, e.g. "Конвейер на 12 октября" (h2). */
  title: React.ReactNode
  value: T
  onValueChange: (value: T) => void
  options: PeriodOption<T>[]
  /** Content for the selected period (KPI, board): rendered as the active tab panel. */
  children: React.ReactNode
  label?: string
  className?: string
}

/**
 * Figma `Period` row: title + `segment` (48px, Сегодня / Неделя / Месяц / Квартал).
 * Built on kit Tabs, so the period switch and the content are a real tablist + tabpanel.
 */
export function PeriodSegment<T extends string>({
  title,
  value,
  onValueChange,
  options,
  children,
  label = "Период",
  className,
}: PeriodSegmentProps<T>) {
  return (
    <Tabs
      value={value}
      onValueChange={(next) => onValueChange(next as T)}
      data-slot="period-segment"
      className={cn("gap-6", className)}
    >
      <div className="flex flex-wrap items-center justify-between gap-4">
        <h2 className="text-xl font-bold text-foreground">{title}</h2>
        <TabsList aria-label={label} className={periodListClass}>
          {options.map((option) => (
            <TabsTrigger
              key={option.value}
              value={option.value}
              className="h-10 flex-1 rounded-md px-2 text-sm font-normal text-soft-foreground sm:flex-none sm:px-4 sm:text-base group-data-[variant=segment]/tabs-list:rounded-md"
            >
              {option.label}
            </TabsTrigger>
          ))}
        </TabsList>
      </div>
      <TabsContent value={value} className="flex flex-col gap-6">
        {children}
      </TabsContent>
    </Tabs>
  )
}
